for case in cases:
    a = mpz(case[0])
    b = mpz(case[1])
    assert str(a + b) == case[2]
    assert str(a - b) == case[3]
    assert str(a * b) == case[4]
    assert str(a // b) == case[5]
    assert str(a % b) == case[6]
    assert str(a & b) == case[7]
    assert str(a | b) == case[8]
    assert str(a ^ b) == case[9]
    assert str(a) == case[0] and str(b) == case[1]
print("exact arithmetic vectors", len(cases), "operations", len(cases) * 8)

small = mpz(7)
assert small + 9 == mpz(16)
assert small - 9 == mpz(-2)
assert small * 9 == mpz(63)
assert small // -3 == mpz(-3)
assert small % -3 == mpz(-2)
assert small & 5 == mpz(5)
assert small | 8 == mpz(15)
assert small ^ 5 == mpz(2)
assert small == 7 and small != 8
assert not small == "7" and small != "7"
assert small < 8 and small <= 7 and small > 6 and small >= 7
assert +small is small
assert str(-small) == "-7" and str(~small) == "-8"
assert str(small.abs()) == "7" and str((-small).abs()) == "7"
assert bool(small) and not bool(mpz())
assert repr(small) == "7"
print("mixed right-int and unary operations passed")

assert small + True == 8 and small - False == 7
assert small * True == 7 and small * False == 0
assert small // True == 7 and small % True == 0
assert small & True == 1 and small | False == 7 and small ^ True == 6
assert mpz(1) == True and mpz(0) == False
assert mpz(0) < True and mpz(1) >= False
for value in [False, True]:
    assert mpz(3) + value == 3 + int(value)
    assert mpz(3) * value == 3 * int(value)
zero_divisors = 0
try:
    small // False
except ZeroDivisionError:
    zero_divisors += 1
try:
    small % False
except ZeroDivisionError:
    zero_divisors += 1
assert zero_divisors == 2
print("mixed right-bool operations passed")
